'Appel.","decor":"temple-du-seuil","position":{"x":960,"y":345},"pnj":[{"id":"mathis"},{"id":"elianne"}],"boutique":["potion-soin-petite","antidote"]},{"id":"lysmont-place","nom":"Place de Lysmont","description":"Le cœur de la capitale : fontaine, étals, rumeurs.","decor":"lysmont-place","position":{"x":960,"y":570},"disponible_si":{"flag":"appel-fait"},"pnj":[{"id":"aveline","si":{"flag":"aveline-rencontree"}}],"boutique":["potion-soin-petite","potion-soin","potion-mana","ration","gateau-lysmont","fleur-des-champs","bijou-dore"]},{"id":"guilde","nom":"Guilde de la Rose des Vents","description":"Le hall des aventuriers : contrats, comptoir et bagarres.","decor":"guilde","position":{"x":1075,"y":610},"disponible_si":{"flag":"appel-fait"},"pnj":[{"id":"rowena"},{"id":"kaya","si":{"flag":"examen-reussi"}}],"boutique":["potion-soin-petite","antidote","bombe-feu","bombe-fumee","epee-courte","dague","arc-court","baton-apprenti","bouclier-bois","armure-cuir","robe-mage","kit-entretien-armes"]},{"id":"taverne","nom":"Le Chaudron Fêlé","description":"La taverne de Bram, où l'on mange bien et où l'on parle trop.","decor":"taverne","position":{"x":845,"y":610},"disponible_si":{"flag":"appel-fait"},"pnj":[{"id":"bram","si":{"pas_flag":"mort:bram"}}],"boutique":["ration","gateau-lysmont","livre-ancien"]},{"id":"chateau","nom":"Château de Lysmont","description":"Le siège de la Couronne, tours blanches et toits bleus.","decor":"chateau-trone","position":{"x":960,"y":480},"disponible_si":{"flag":"appel-fait"},"pnj":[{"id":"edmund-iv"},{"id":"seraphine"}],"boutique":[]},{"id":"quartier-tanneurs","nom":"Quartier des Tanneurs","description":"Ruelles pauvres et cuves de teinture. On y disparaît, ces temps-ci.","decor":"quartier-tanneurs","position":{"x":1060,"y":680},"disponible_si":{"flag":"examen-reussi"},"pnj":[],"boutique":[]},{"id":"arene","nom":"Arène de Lysmont","description":"Le sable du tournoi des écuyers.","decor":"arene","position":{"x":1120,"y":530},"disponible_si":{"flag":"examen-reussi"},"pnj":[],"boutique":[]},{"id":"combe-aux-saules","nom":"Combe-aux-Saules","description":"Forêt de saules au sud-ouest, fermes isolées et loups affamés.","decor":"combe-aux-saules","position":{"x":440,"y":790},"disponible_si":{"flag":"examen-reussi"},"pnj":[],"boutique":[]},{"id":"crypte-fontaine","nom":"Crypte de la Fontaine","description":"Des ruines couvertes de lierre, un escalier qui descend dans le noir.","decor":"crypte-entree","position":{"x":1488,"y":500},"disponible_si":{"quete_etape":{"q-ch1-appel":"crypte"}},"pnj":[],"boutique":[]}]}},"pnj":{"mathis":{"id":"mathis","nom":"Grand Prieur Mathis","titre":"Ordre de la Lumière Sereine","description":"Crâne rasé, barbe blanche, sourire bienveillant un peu trop parfait."},"rowena":{"id":"rowena","nom":"Dame Rowena","titre":"Maîtresse de la Guilde","description":"Cheveux gris coupés court, cicatrice sur l'œil, pipe éteinte entre les dents."},"edmund-iv":{"id":"edmund-iv","nom":"Edmund IV","titre":"Roi d'Aubeclaire","description":"Couronne lourde, barbe grise, regard fatigué et dur."},"seraphine":{"id":"seraphine","nom":"Séraphine d'Aubeclaire","titre":"Princesse","description":"Seconde de la lignée, espiègle sous l'étiquette."},"elianne":{"id":"elianne","nom":"Sœur Elianne","titre":"Prêtresse","description":"Douce, patiente, têtue quand il s'agit de justice."},"kaya":{"id":"kaya","nom":"Kaya Lunecroc","titre":"Aventurière ourvalis, rang E","description":"Oreilles de loup argentées, franche jusqu'à la gaffe."},"vorthak":{"id":"vorthak","nom":"Vorthak","titre":"Émissaire des Cendres","description":"Démon en armure noire aux flammes violettes."},"ferrand":{"id":"ferrand","nom":"Ferrand","titre":"Marchand de reliques","description":"Sourire huileux, manteau trop beau pour son commerce."},"bram":{"id":"bram","nom":"Bram","titre":"Tavernier du Chaudron Fêlé","description":"Colosse jovial, tablier taché, cœur d'or."},"lina":{"id":"lina","nom":"Lina","titre":"Jeune tanneuse","description":"Disparue du quartier des Tanneurs."},"tobin":{"id":"tobin","nom":"Tobin","titre":"Apprenti de l'Ordre","description":"Dix-neuf ans, curieux, trop curieux."},"gareth":{"id":"gareth","nom":"Gareth","titre":"Fermier de la Combe-aux-Saules","description":"Mains calleuses, chapeau de paille."},"mentor":{"id":"mentor","nom":"Maître Orlo","titre":"Mentor d'enfance","description":"Vieux bibliothécaire bourru."},"rival":{"id":"rival","nom":"Cassian","titre":"Rival d'enfance","description":"Fils de garde, fier et rapide."},"ami-enfance":{"id":"ami-enfance","nom":"Pipa","titre":"Amie d'enfance","description":"Rieuse, intrépide, toujours une égratignure au genou."}},"scenes":{"av-ronde":{"id":"av-ronde","titre":"Aveline — La ronde de nuit","type":"individuel","lieu":"lysmont-place","decor":"lysmont-place","debut":"debut","disponible_si":{"flag":"examen-reussi"},"repetable":false,"romance":false,"noeuds":{"debut":{"repliques":[{"qui":"aveline","expression":"neutre","dit":"Vous croisez Aveline pendant sa ronde, une lanterne à la main. « Encore debout ? Les héros ne dorment jamais, c'est ça ? »"}],"effets":[],"choix":[{"texte":"« Je pourrais vous accompagner. Deux paires d'yeux valent mieux qu'une. »","visible_si_bloque":false,"effets":[{"affinite":{"aveline":5}}],"aller":"accompagne"},{"texte":"« Et vous, capitaine ? Vous ne dormez jamais non plus. »","visible_si_bloque":false,"effets":[{"affinite":{"aveline":3}}],"aller":"question"},{"texte":"« Ce n'est pas un peu ennuyeux, de tourner en rond toute la nuit ? »","visible_si_bloque":false,"effets":[{"affinite":{"aveline":-2}}],"aller":"vexee"}],"fin":false},"accompagne":{"repliques":[{"qui":"aveline","expression":"neutre","dit":"Elle hésite, puis hoche la tête. Vous marchez longtemps en silence. C'est un silence étonnamment agréable."},{"qui":"aveline","expression":"joie","dit":"Au détour d'une rue, elle s'arrête net devant une pâtisserie fermée, le nez presque collé à la vitre. Puis elle se reprend. « Je… vérifiais les serrures. »"}],"effets":[{"flag":"heros:secret-patisserie"}],"choix":[],"suite":"fin","fin":false},"question":{"repliques":[{"qui":"aveline","expression":"tristesse","dit":"« Pas beaucoup, non. » Elle regarde vers le nord. « Quand je ferme les yeux, je vois Valgrane. » Elle n'en dit pas plus."}],"effets":[],"choix":[],"suite":"fin","fin":false},"vexee":{"repliques":[{"qui":"aveline","expression":"colere","dit":"« C'est ce qui permet à la ville de dormir tranquille. » Elle s'éloigne d'un pas raide."}],"effets":[],"choix":[],"suite":"fin","fin":false},"fin":{"repliques":[],"effets":[],"choix":[],"fin":true}}},"av-entrainement":{"id":"av-entrainement","titre":"Aveline — Leçon d'escrime","type":"individuel","lieu":"chateau","decor":"chateau-trone","debut":"debut","disponible_si":{"flag":"examen-reussi","affinite_min":{"aveline":10}},"repetable":false,"romance":false,"noeuds":{"debut":{"repliques":[{"qui":"aveline","expression":"neutre","dit":"Dans la cour du château, Aveline vous lance une épée de bois. « Votre garde est catastrophique. Montrez-moi ce que vous savez faire. »"}],"effets":[],"choix":[{"texte":"Vous battre sérieusement. (Force, difficulté 16)","visible_si_bloque":false,"test":{"carac":"FOR","difficulte":16,"reussite":"gagne","echec":"perd"},"effets":[]},{"texte":"Esquiver et la faire tourner en bourrique. (Agilité, difficulté 16)","visible_si_bloque":false,"test":{"carac":"AGI","difficulte":16,"reussite":"gagne","echec":"perd"},"effets":[]},{"texte":"Tricher : lui jeter du sable aux yeux.","visible_si_bloque":false,"effets":[{"affinite":{"aveline":-6}}],"aller":"triche"}],"fin":false},"gagne":{"repliques":[{"qui":"aveline","expression":"surprise","dit":"Votre lame de bois s'arrête à un doigt de sa gorge. Elle vous fixe, sidérée… puis éclate de rire. Un vrai rire."},{"qui":"aveline","expression":"joie","dit":"« Encore. Demain. Même heure. » Ce n'est pas une question."}],"effets":[{"affinite":{"aveline":7},"xp":40}],"choix":[],"suite":"fin","fin":false},"perd":{"repliques":[{"qui":"aveline","expression":"neutre","dit":"Vous voilà sur le dos, sa lame de bois sur votre poitrine. « Pas mal. Pour un débutant. » Elle vous tend la main pour vous relever."}],"effets":[{"affinite":{"aveline":4},"xp":25}],"choix":[],"suite":"fin","fin":false},"triche":{"repliques":[{"qui":"aveline","expression":"colere","dit":"Elle crache le sable, furieuse. « Sur un champ de bataille, peut-être. Ici, c'est une leçon d'honneur. Recommencez quand vous en aurez. »"}],"effets":[],"choix":[],"suite":"fin","fin":false},"fin":{"repliques":[],"effets":[],"choix":[],"fin":true}}},"av-confidence":{"id":"av-confidence","titre":"Aveline — Ce qu'on ne dit à personne","type":"individuel","lieu":"taverne","decor":"taverne","debut":"debut","disponible_si":{"affinite_palier":{"aveline":"proche"}},"repetable":false,"romance":false,"noeuds":{"debut":{"repliques":[{"qui":"aveline","expression":"neutre","dit":"Aveline vous attend au fond de la taverne, devant deux chopes qu'elle n'a pas touchées. « Asseyez-vous. J'ai… quelque chose à vous dire. »"},{"qui":"aveline","expression":"tristesse","dit":"« Mon père, Gauvain de Castelroc, commandait Valgrane. On l'a accusé d'avoir ouvert les portes aux Cendres. On l'a exécuté sans procès. »"},{"qui":"aveline","expression":"neutre","dit":"« Je n'ai jamais cru à sa trahison. Mais les archives militaires de Valgrane ont été scellées… par l'Ordre. Pourquoi l'Ordre ? »"}],"effets":[],"choix":[{"texte":"« Je vous aiderai à découvrir la vérité. Je vous en fais la promesse. »","visible_si_bloque":false,"effets":[{"flag":"heros:promesse-aveline","affinite":{"aveline":8},"quete":{"id":"q-aveline","etape":"archives"}}],"aller":"promesse"},{"texte":"« Et si la vérité ne vous plaisait pas ? »","visible_si_bloque":false,"effets":[{"affinite":{"aveline":3},"quete":{"id":"q-aveline","etape":"archives"}}],"aller":"prudent"}],"fin":false},"promesse":{"repliques":[{"qui":"aveline","expression":"gene","dit":"Elle vous regarde longtemps. Puis, très doucement, elle pose sa main sur la vôtre. « Merci. » Elle la retire aussitôt, écarlate."}],"effets":[],"choix":[],"suite":"fin","fin":false},"prudent":{"repliques":[{"qui":"aveline","expression":"neutre","dit":"« Alors au moins, je saurai. » Elle lève sa chope. « À la vérité, quelle qu'elle soit. »"}],"effets":[],"choix":[],"suite":"fin","fin":false},"fin":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"(Quête de compagnon « Le Serment brisé » : la suite au chapitre 2.)"}],"effets":[],"choix":[],"fin":true}}},"av-remparts":{"id":"av-remparts","titre":"Aveline — Les remparts au crépuscule","type":"individuel","lieu":"chateau","decor":"chateau-trone","debut":"debut","disponible_si":{"affinite_palier":{"aveline":"amoureuse"}},"repetable":false,"romance":true,"noeuds":{"debut":{"repliques":[{"qui":"aveline","expression":"neutre","dit":"Le soleil se couche sur Lysmont. Aveline est assise sur le parapet, les jambes dans le vide, sans armure."},{"qui":"aveline","expression":"gene","dit":"« Je ne suis pas douée pour… ça. Les mots. » Elle fixe l'horizon. « Avec une épée, je sais toujours quoi faire. Avec vous, jamais. »"}],"effets":[],"choix":[{"texte":"Vous asseoir à côté d'elle et prendre sa main.","visible_si_bloque":false,"effets":[{"affinite":{"aveline":5}}],"aller":"main"},{"texte":"« Alors ne dites rien. »","visible_si_bloque":false,"effets":[{"affinite":{"aveline":5}}],"aller":"main"}],"fin":false},"main":{"repliques":[{"qui":"aveline","expression":"joie","dit":"Elle rit doucement, nerveusement, et pose la tête sur votre épaule. Le soleil disparaît derrière les tours blanches…"},{"qui":"narrateur","expression":"neutre","dit":"(Fondu au noir.)"}],"effets":[],"choix":[],"fin":true}}},"ch1-appel":{"id":"ch1-appel","titre":"L'Appel","type":"groupe","lieu":"temple-du-seuil","decor":"temple-du-seuil","debut":"debut","disponible_si":{"pas_flag":"appel-fait"},"repetable":false,"romance":false,"quete":"q-ch1-appel","noeuds":{"debut":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Printemps 1012. Un cercle de lumière bleue embrase le sol du Temple du Seuil. Des chants montent, des vitraux vibrent… puis le silence."},{"qui":"narrateur","expression":"neutre","dit":"Au centre du cercle, des silhouettes se relèvent, hagardes : les invoqués. À la lisière de la lumière, d'autres jeunes gens, attirés ici par une résonance qu'ils ne savent pas nommer : les réincarnés.","si":{"origine":"reincarne"}},{"qui":"mathis","expression":"neutre","dit":"« Bienvenue à Velmaris, Appelés. Je suis Mathis, Grand Prieur de l'Ordre de la Lumière Sereine. N'ayez crainte : la Lumière vous a choisis. »"},{"qui":"mathis","expression":"neutre","dit":"« Le Souverain des Cendres s'est éveillé au nord. Le Mur d'Aube faiblit. Le royaume a besoin de héros. »"},{"qui":"aveline","expression":"neutre","dit":"Une jeune femme en armure argentée s'avance, la main sur le pommeau. « Capitaine Aveline de Castelroc. Je suis chargée de votre sécurité. » Son regard s'attarde sur vous, méfiant."}],"effets":[],"choix":[{"texte":"« Un monde de magie ? Génial. Où est-ce qu'on signe ? » (enthousiaste)","visible_si_bloque":false,"effets":[{"reputation":{"ordre":5},"affinite":{"aveline":2}}],"aller":"enthousiaste"},{"texte":"« Personne ne nous a demandé notre avis. Qui a décidé de nous arracher à nos vies ? » (méfiant)","visible_si_bloque":false,"effets":[{"flag":"mefiance-ordre","reputation":{"ordre":-5},"affinite":{"aveline":4}}],"aller":"mefiant"},{"texte":"« Excusez-moi, il y a des toilettes dans ce monde ? » (humour)","visible_si_bloque":false,"effets":[{"affinite":{"aveline":3}}],"aller":"humour"}],"fin":false},"enthousiaste":{"repliques":[{"qui":"mathis","expression":"neutre","dit":"Le Grand Prieur sourit largement. « Voilà l'esprit des héros ! »"},{"qui":"aveline","expression":"neutre","dit":"Aveline soupire. « Les derniers à avoir dit ça sont enterrés sous le Mur d'Aube. »"}],"effets":[],"choix":[],"suite":"suite","fin":false},"mefiant":{"repliques":[{"qui":"mathis","expression":"neutre","dit":"Le sourire du Grand Prieur se fige une fraction de seconde. « La Lumière a ses raisons. Vous les comprendrez. »"},{"qui":"aveline","expression":"neutre","dit":"Aveline vous jette un regard nouveau. Presque… approbateur."}],"effets":[],"choix":[],"suite":"suite","fin":false},"humour":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Un acolyte s'étrangle. Mathis cligne des yeux."},{"qui":"aveline","expression":"joie","dit":"Aveline détourne la tête, mais vous l'avez vue : elle a souri. « Par ici. Et oui, il y en a. »"}],"effets":[],"choix":[],"suite":"suite","fin":false},"suite":{"repliques":[{"qui":"mathis","expression":"neutre","dit":"« Reposez-vous. Demain, la Couronne vous recevra. En attendant, la Guilde de la Rose des Vents vous ouvrira ses portes : vous y apprendrez à survivre. »"},{"qui":"narrateur","expression":"neutre","dit":"Ce soir-là, en contemplant les tours blanches de Lysmont depuis la fenêtre du temple, chacun de vous voit flotter devant ses yeux une fenêtre translucide : votre niveau, vos capacités… et votre don."}],"effets":[{"flag":["appel-fait","aveline-rencontree"],"quete":{"id":"q-ch1-appel","etape":"examen"},"recruter":"aveline","journal":"L'Appel : {groupe} arrivent au Temple du Seuil. La capitaine Aveline de Castelroc est chargée de leur sécurité."}],"choix":[],"fin":true}}},"ch1-examen":{"id":"ch1-examen","titre":"L'examen de la Guilde","type":"groupe","lieu":"guilde","decor":"guilde","debut":"debut","disponible_si":{"quete_etape":{"q-ch1-appel":"examen"}},"repetable":false,"romance":false,"quete":"q-ch1-appel","noeuds":{"debut":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Solaire 1012. Le hall de la Guilde de la Rose des Vents sent la bière, le cuir et la sueur. Des dizaines de regards se tournent vers vous."},{"qui":"rowena","expression":"neutre","dit":"« Ah. Les Appelés. » Dame Rowena mâchonne sa pipe éteinte. « Ici, votre don ne vaut rien tant que vous n'avez pas prouvé que vous savez tenir debout. »"},{"qui":"kaya","expression":"neutre","dit":"Une jeune femme aux oreilles de loup argentées vous dévisage, adossée à un pilier. « Pff. Ils ont l'air tout mous. Je parie dix pièces qu'ils tombent au premier coup. »"},{"qui":"kaya","expression":"neutre","dit":"Elle vous fixe un instant de plus, puis son regard s'adoucit. « …Un Ourvalis ? Hé. Bonne chance, alors. »","si":{"race":"ourvalis"}},{"qui":"rowena","expression":"neutre","dit":"« L'examen est simple : vous affrontez notre golem d'entraînement. S'il vous met au tapis, revenez dans un an. »"}],"effets":[{"aller_date":{"annee":1012,"mois":4,"jour":5}}],"choix":[{"texte":"Entrer dans l'arène d'entraînement.","visible_si_bloque":false,"effets":[],"aller":"combat"},{"texte":"« Kaya, c'est ça ? Je double ta mise : vingt pièces que tu perds. »","visible_si_bloque":false,"effets":[{"flag":"pari-kaya"}],"aller":"combat"}],"fin":false},"combat":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Le golem d'argile se met en marche dans un grincement."}],"effets":[],"choix":[],"combat":{"rencontre":"examen-guilde","victoire":"victoire","defaite":"defaite"},"fin":false},"victoire":{"repliques":[{"qui":"rowena","expression":"neutre","dit":"« Pas mal. Pas mal du tout. » Elle tamponne une carte de cuivre. « Rang F. Les contrats sont au tableau. Ne mourez pas bêtement. »"},{"qui":"kaya","expression":"neutre","dit":"Kaya vous tend dix pièces en grommelant. « Ouais, bon. Vous avez de la chance. »","si":{"flag":"pari-kaya"}}],"effets":[{"flag":"examen-reussi","points_guilde":50,"quete":{"id":"q-ch1-appel","etape":"crypte"},"journal":"{groupe} réussissent l'examen de la Guilde : rang F."}],"choix":[],"suite":"ellipse","fin":false},"defaite":{"repliques":[{"qui":"rowena","expression":"neutre","dit":"« Bon. Le golem vous a laminés. » Elle soupire. « Mais vous vous êtes relevés. C'est ce que je cherche. Rang F, à l'essai. »"}],"effets":[{"flag":"examen-reussi","points_guilde":20,"quete":{"id":"q-ch1-appel","etape":"crypte"},"journal":"{groupe} entrent à la Guilde « à l'essai »."}],"choix":[],"suite":"ellipse","fin":false},"ellipse":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Les mois passent. Contrats, entraînements, premières cicatrices. Lysmont devient peu à peu votre ville."},{"qui":"aveline","expression":"neutre","dit":"Aveline passe souvent « par hasard » à la Guilde. Officiellement pour vous surveiller."}],"effets":[{"ellipse":{"jusqua":{"annee":1013,"mois":7,"jour":1},"titre":"Premiers mois à la Guilde"}}],"choix":[],"fin":true}}},"ch1-crypte":{"id":"ch1-crypte","titre":"La Crypte de la Fontaine","type":"groupe","lieu":"crypte-fontaine","decor":"crypte-entree","debut":"debut","disponible_si":{"quete_etape":{"q-ch1-appel":"crypte"}},"repetable":false,"romance":false,"quete":"q-ch1-appel","noeuds":{"debut":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Brumaire 1013. Des paysans ont vu des lueurs violettes sous les ruines de la Crypte de la Fontaine. Rowena vous a confié l'affaire."},{"qui":"aveline","expression":"neutre","dit":"Aveline vous attend à l'entrée, en armure complète. « Ordre du roi : je vous accompagne. Et… je n'allais pas vous laisser descendre seuls. »"},{"qui":"narrateur","expression":"neutre","dit":"L'escalier s'enfonce dans le noir. Une odeur d'eau croupie et de vieille pierre monte des profondeurs."}],"effets":[],"choix":[{"texte":"Descendre dans la crypte.","visible_si_bloque":false,"effets":[],"aller":"donjon"}],"fin":false},"donjon":{"repliques":[],"effets":[],"choix":[],"donjon":{"id":"crypte-fontaine","sortie":"sortie"},"fin":false},"sortie":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Vous remontez à la surface, couverts de poussière. Dans votre sac, le sceau cendré pulse d'une lumière violette, comme un cœur."},{"qui":"aveline","expression":"colere","dit":"« Ce symbole… » Aveline pâlit. « On l'a trouvé sur les ruines de Valgrane, il y a dix ans. Le jour où mon père… » Elle se tait."}],"effets":[{"flag":"sceau-trouve","xp":60,"quete":{"id":"q-ch1-appel","etape":"lanternes"},"journal":"Dans la Crypte de la Fontaine, {groupe} découvrent un sceau cendré."}],"choix":[{"texte":"Remettre le sceau à l'Ordre, comme le veut la loi.","visible_si_bloque":false,"effets":[{"flag":"sceau-ordre","reputation":{"ordre":10}}],"aller":"ellipse"},{"texte":"Le confier à la Guilde : Rowena saura quoi en faire.","visible_si_bloque":false,"effets":[{"flag":"sceau-guilde","reputation":{"guilde":10}}],"aller":"ellipse"},{"texte":"Le garder et l'étudier vous-mêmes, en secret.","visible_si_bloque":false,"effets":[{"flag":"sceau-garde","affinite":{"aveline":2}}],"aller":"ellipse"}],"fin":false},"ellipse":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"L'hiver tombe sur Lysmont. Le sceau ne quitte pas vos pensées."}],"effets":[{"ellipse":{"jusqua":{"annee":1014,"mois":2,"jour":15},"titre":"L'hiver à Lysmont"}}],"choix":[],"fin":true}}},"ch1-lanternes":{"id":"ch1-lanternes","titre":"La Nuit des Lanternes","type":"groupe","lieu":"lysmont-place","decor":"lysmont-lanternes-nuit","debut":"debut","disponible_si":{"quete_etape":{"q-ch1-appel":"lanternes"}},"repetable":false,"romance":false,"quete":"q-ch1-appel","noeuds":{"debut":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"15 Floréal 1014, Fête des Lanternes. Des milliers de lanternes de papier s'élèvent au-dessus de Lysmont, chacune portant le nom d'un disparu."},{"qui":"bram","expression":"neutre","dit":"Bram, le tavernier, distribue des brochettes en riant. « Ce soir, c'est la maison qui régale ! »","si":{"pas_flag":"mort:bram"}},{"qui":"seraphine","expression":"neutre","dit":"Sur le balcon du château, une jeune femme blonde vous fait un petit signe discret. La princesse Séraphine."},{"qui":"aveline","expression":"neutre","dit":"Aveline est là elle aussi, en civil pour une fois, une lanterne éteinte entre les doigts."},{"qui":"aveline","expression":"gene","dit":"« C'est… pour mon père. » Elle hésite, sans vous regarder. « Vous voulez bien rester un moment ? »","si":{"affinite_min":{"aveline":20}}}],"effets":[],"choix":[{"texte":"Lâcher une lanterne avec Aveline, en silence.","si":{"affinite_min":{"aveline":20}},"visible_si_bloque":false,"effets":[{"flag":"heros:lanterne-aveline","affinite":{"aveline":6}}],"aller":"lanterne"},{"texte":"Profiter de la fête : danses, musique, brochettes.","visible_si_bloque":false,"effets":[{"affinite":{"aveline":1}}],"aller":"attaque"}],"fin":false},"lanterne":{"repliques":[{"qui":"aveline","expression":"tristesse","dit":"Vos lanternes montent côte à côte. Aveline murmure : « Il s'appelait Gauvain. Il n'était pas un traître. » Pour la première fois, sa voix tremble."},{"qui":"aveline","expression":"gene","dit":"Elle s'essuie les yeux d'un revers de main. « …Merci. N'en parlez à personne. »"}],"effets":[],"choix":[],"suite":"attaque","fin":false},"attaque":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Soudain, les lanternes virent au violet. Un cri. Puis une explosion de cendres au centre de la place."},{"qui":"narrateur","expression":"neutre","dit":"Des gobelins cendrés surgissent des égouts, guidés par des cultistes. La foule panique."},{"qui":"aveline","expression":"colere","dit":"« Protégez les civils ! » hurle Aveline en dégainant."}],"effets":[],"choix":[{"texte":"Couvrir la fuite des civils, même si les cultistes s'échappent.","visible_si_bloque":false,"effets":[{"flag":"civils-proteges","reputation":{"couronne":5},"affinite":{"aveline":5}}],"aller":"combat1"},{"texte":"Foncer sur le cultiste qui dirige l'attaque, coûte que coûte.","visible_si_bloque":false,"effets":[{"flag":["heros:civils-abandonnes","cultiste-poursuivi"],"reputation":{"guilde":5}}],"aller":"combat1"}],"fin":false},"combat1":{"repliques":[],"effets":[],"choix":[],"combat":{"rencontre":"lanternes-cultistes","victoire":"vorthak","defaite":"defaite1"},"fin":false},"defaite1":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Vous tombez sous le nombre. Quand vous rouvrez les yeux, la garde a repoussé les gobelins… mais le Chaudron Fêlé est en flammes."}],"effets":[{"pnj_mort":"bram"}],"choix":[],"suite":"vorthak","fin":false},"vorthak":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Les flammes s'ouvrent. Une silhouette en armure noire s'avance, une épée nimbée de feu violet à la main."},{"qui":"vorthak","expression":"neutre","dit":"« Alors c'est vous, les nouveaux jouets de l'Ordre. » Il rit. « Le Souverain m'a demandé de vous saluer. »"},{"qui":"vorthak","expression":"neutre","dit":"« Le sceau. Vous l'avez. Je le sens. Rendez-le-moi, et je laisse vivre cette ville une année de plus. »","si":{"flag":"sceau-garde"}}],"effets":[],"choix":[{"texte":"« Viens le chercher. »","visible_si_bloque":false,"effets":[],"aller":"combat2"},{"texte":"« Pourquoi vous attaquez Lysmont ? Qu'est-ce que vous voulez vraiment ? » (Esprit, difficulté 17)","visible_si_bloque":false,"test":{"carac":"ESP","difficulte":17,"reussite":"revelation","echec":"combat2"},"effets":[]}],"fin":false},"revelation":{"repliques":[{"qui":"vorthak","expression":"neutre","dit":"Il incline la tête, amusé. « Ce que nous voulons ? Demandez à votre Grand Prieur combien coûte un Appel. Demandez-lui qui paie. »"}],"effets":[{"flag":"indice-prix-appel"}],"choix":[],"suite":"combat2","fin":false},"combat2":{"repliques":[],"effets":[],"choix":[],"combat":{"rencontre":"lanternes-vorthak","victoire":"victoire","defaite":"defaite2"},"fin":false},"victoire":{"repliques":[{"qui":"vorthak","expression":"neutre","dit":"Vorthak recule, son armure fendue. « Intéressant… très intéressant. » Il disparaît dans un tourbillon de cendres."},{"qui":"aveline","expression":"joie","dit":"Aveline s'appuie sur son épée, essoufflée, et vous regarde avec un sourire épuisé. « Vous… vous avez été incroyables. »"}],"effets":[{"reputation":{"couronne":10,"guilde":5},"affinite":{"aveline":4}}],"choix":[],"suite":"bilan","fin":false},"defaite2":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Vorthak vous balaie comme des fétus de paille, puis s'en va, l'air ennuyé. « Revenez quand vous serez dignes de mon temps. »"}],"effets":[{"reputation":{"couronne":-5}}],"choix":[],"suite":"bilan","fin":false},"bilan":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"À l'aube, Lysmont compte ses morts. Les lanternes calcinées jonchent les pavés."},{"qui":"bram","expression":"neutre","dit":"Bram, couvert de suie, vous serre la main à vous broyer les os. « Vous avez sauvé ma taverne. Ici, vous ne paierez plus jamais une bière. »","si":{"flag":"civils-proteges","pas_flag":"mort:bram"}},{"qui":"narrateur","expression":"neutre","dit":"Le Chaudron Fêlé n'est plus que cendres. Bram n'a pas survécu.","si":{"flag":"mort:bram"}}],"effets":[{"flag":"lanternes-faites","quete":{"id":"q-ch1-appel","etape":"serment"},"journal":"Fête des Lanternes : Vorthak, émissaire des Cendres, attaque Lysmont."},{"aller_date":{"annee":1014,"mois":10,"jour":3}}],"choix":[],"fin":true}}},"ch1-serment":{"id":"ch1-serment","titre":"Le Serment","type":"groupe","lieu":"chateau","decor":"chateau-trone","debut":"debut","disponible_si":{"quete_etape":{"q-ch1-appel":"serment"}},"repetable":false,"romance":false,"quete":"q-ch1-appel","noeuds":{"debut":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Nivôse 1014. La salle du trône est glaciale. Le roi Edmund IV vous toise depuis son trône doré."},{"qui":"edmund-iv","expression":"neutre","dit":"« Vous avez défendu ma capitale. Bien. Mais un héros sans maître est une épée sans fourreau : dangereux. »"},{"qui":"edmund-iv","expression":"neutre","dit":"« Agenouillez-vous et jurez fidélité à la Couronne. Vous aurez titres, or, et l'honneur de mourir pour Aubeclaire. »"},{"qui":"seraphine","expression":"neutre","dit":"La princesse Séraphine, debout à côté du trône, serre les poings. Elle croise votre regard et secoue très légèrement la tête."},{"qui":"aveline","expression":"neutre","dit":"Aveline, au garde-à-vous, fixe un point droit devant elle. Mais ses jointures blanchissent sur son épée."}],"effets":[],"choix":[{"texte":"Jurer fidélité à la Couronne.","visible_si_bloque":false,"effets":[{"flag":"serment-couronne","reputation":{"couronne":15,"guilde":-5},"affinite":{"aveline":2}}],"aller":"jure"},{"texte":"Refuser poliment : vous resterez des aventuriers libres, fidèles à la Guilde.","visible_si_bloque":false,"effets":[{"flag":"independants","reputation":{"couronne":-10,"guilde":15}}],"aller":"refus"},{"texte":"Négocier : une alliance d'égal à égal, pas un serment de vassal. (Charisme, difficulté 18)","visible_si_bloque":false,"test":{"carac":"CHA","difficulte":18,"reussite":"negociation","echec":"negociation-ratee"},"effets":[]},{"texte":"Faire semblant de jurer, en croisant les doigts dans votre dos.","visible_si_bloque":false,"effets":[{"flag":["serment-couronne","heros:parole-trahie"],"reputation":{"couronne":10}}],"aller":"faux"}],"fin":false},"jure":{"repliques":[{"qui":"edmund-iv","expression":"neutre","dit":"« Relevez-vous, chevaliers d'Aubeclaire. » Le roi sourit enfin. Séraphine détourne les yeux."}],"effets":[],"choix":[],"suite":"epilogue","fin":false},"refus":{"repliques":[{"qui":"edmund-iv","expression":"neutre","dit":"Un silence de mort. « …Soit. La Guilde répondra de vous. Ne me décevez pas. »"},{"qui":"seraphine","expression":"neutre","dit":"En sortant, Séraphine vous rattrape dans un couloir. « C'était courageux. Ou stupide. Les deux me plaisent. »"}],"effets":[],"choix":[],"suite":"epilogue","fin":false},"negociation":{"repliques":[{"qui":"edmund-iv","expression":"neutre","dit":"Le roi plisse les yeux… puis éclate d'un rire bref. « Vous avez du cran. Une alliance, donc. Mais je m'en souviendrai. »"}],"effets":[{"flag":"allies-libres","reputation":{"couronne":5,"guilde":5}}],"choix":[],"suite":"epilogue","fin":false},"negociation-ratee":{"repliques":[{"qui":"edmund-iv","expression":"neutre","dit":"« Des conditions ? À MOI ? » Le roi se lève, furieux. « Hors de ma vue ! »"}],"effets":[{"flag":"independants","reputation":{"couronne":-15,"guilde":10}}],"choix":[],"suite":"epilogue","fin":false},"faux":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Vous prononcez les mots du serment. Personne ne remarque vos doigts croisés… sauf Aveline, juste derrière vous. Son visage se ferme."}],"effets":[],"choix":[],"suite":"epilogue","fin":false},"epilogue":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Ce soir-là, sur les remparts, vous regardez les étoiles d'un ciel qui n'est pas le vôtre."},{"qui":"aveline","expression":"neutre","dit":"« Le printemps prochain, on m'envoie à la frontière sud. » Aveline hésite. « J'aimerais… que vous veniez. » Elle rougit. « Pour la mission, évidemment. »","si":{"affinite_min":{"aveline":35}}},{"qui":"narrateur","expression":"neutre","dit":"Deux ans ont passé depuis l'Appel. Velmaris n'est plus un monde étranger : c'est le vôtre, désormais. Et il brûle déjà au nord."}],"effets":[{"xp":150,"terminer_quete":"q-ch1-appel"},{"ellipse":{"jusqua":{"annee":1015,"mois":1,"jour":1},"titre":"La fin de l'an 1014"},"fin_chapitre":1}],"choix":[],"fin":true}}},"sq-loups":{"id":"sq-loups","titre":"Les loups de la Combe-aux-Saules","type":"groupe","lieu":"combe-aux-saules","decor":"combe-aux-saules","debut":"debut","disponible_si":{"flag":"examen-reussi"},"repetable":false,"romance":false,"quete":"q-loups","noeuds":{"debut":{"repliques":[{"qui":"gareth","expression":"neutre","dit":"« Trois moutons cette semaine ! Et hier, ma petite Rose a vu des yeux jaunes à la lisière. » Gareth tord son chapeau de paille entre ses mains."},{"qui":"narrateur","expression":"neutre","dit":"Les traces mènent à une tanière sous les racines d'un vieux saule. Des grognements… et des gémissements plus aigus : des louveteaux."}],"effets":[{"quete":{"id":"q-loups","etape":"aider"}}],"choix":[{"texte":"Attaquer la meute.","visible_si_bloque":false,"effets":[],"aller":"combat"},{"texte":"Utiliser votre don pour parler à la louve. (Langue universelle)","si":{"don":"langue-universelle"},"visible_si_bloque":false,"effets":[],"aller":"parler"},{"texte":"Effrayer la meute avec du feu et du bruit pour la faire partir. (Force, difficulté 16)","visible_si_bloque":false,"test":{"carac":"FOR","difficulte":16,"reussite":"fuite","echec":"combat"},"effets":[]}],"fin":false},"parler":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"La louve vous écoute, babines retroussées. Puis, lentement, elle comprend : les fermiers, les pièges, les bois plus au sud où le gibier abonde."},{"qui":"narrateur","expression":"neutre","dit":"À l'aube, la meute est partie. Gareth n'en croit pas ses yeux."}],"effets":[{"flag":"loups-sauves","xp":80}],"choix":[],"suite":"fin","fin":false},"fuite":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Torches, cris, casseroles : la meute détale vers le sud avec ses petits. Aucun sang versé."}],"effets":[{"flag":"loups-sauves","xp":60}],"choix":[],"suite":"fin","fin":false},"combat":{"repliques":[],"effets":[],"choix":[],"combat":{"rencontre":"loups-alpha","victoire":"victoire","defaite":"defaite"},"fin":false},"victoire":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"La meute est décimée. Les louveteaux s'enfuient dans les fourrés."}],"effets":[],"choix":[],"suite":"fin","fin":false},"defaite":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Les loups vous repoussent. Gareth vous traîne jusqu'à sa ferme et vous soigne avec une soupe épaisse. « On réessaiera. »"}],"effets":[],"choix":[],"suite":"fin","fin":false},"fin":{"repliques":[{"qui":"gareth","expression":"neutre","dit":"« Merci, du fond du cœur. Tenez, c'est pas grand-chose, mais c'est honnête. »"}],"effets":[{"reputation":{"guilde":3},"or":25,"points_guilde":30,"terminer_quete":"q-loups"}],"choix":[],"fin":true}}},"sq-reliques":{"id":"sq-reliques","titre":"Le marchand de reliques","type":"groupe","lieu":"taverne","decor":"taverne","debut":"debut","disponible_si":{"flag":"examen-reussi"},"repetable":false,"romance":false,"quete":"q-reliques","noeuds":{"debut":{"repliques":[{"qui":"ferrand","expression":"neutre","dit":"« Approchez, approchez ! Un os authentique de Saint Aldebrand, le Premier Appelé ! Il guérit les fièvres et porte chance aux aventuriers. Cent pièces seulement ! »"},{"qui":"bram","expression":"neutre","dit":"Bram lève les yeux au ciel derrière son comptoir. « Ça fait trois semaines qu'il vend des os de poulet. »","si":{"pas_flag":"mort:bram"}}],"effets":[{"quete":{"id":"q-reliques","etape":"enqueter"}}],"choix":[{"texte":"Examiner la « relique » de près. (Intelligence, difficulté 15)","visible_si_bloque":false,"test":{"carac":"INT","difficulte":15,"reussite":"demasque","echec":"rate"},"effets":[]},{"texte":"L'acheter. On ne sait jamais.","si":{"or_min":100},"visible_si_bloque":false,"effets":[{"or":-100,"objet":"relique-douteuse"}],"aller":"achete"},{"texte":"Aller prévenir l'Ordre : vendre de fausses reliques est un crime.","visible_si_bloque":false,"effets":[],"aller":"ordre"}],"fin":false},"demasque":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Un os de poulet, verni et gravé à la hâte. Vous le brandissez sous le nez des clients. Rires, huées : Ferrand s'enfuit sous les quolibets."}],"effets":[{"flag":"ferrand-demasque","reputation":{"guilde":5},"xp":50}],"choix":[],"suite":"fin","fin":false},"rate":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"L'os a l'air… vrai ? Vous n'en êtes pas sûrs. Ferrand vous adresse un clin d'œil satisfait."}],"effets":[],"choix":[],"suite":"fin","fin":false},"achete":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Ferrand empoche l'or avec un sourire radieux. La relique sent vaguement le poulet rôti."}],"effets":[],"choix":[],"suite":"fin","fin":false},"ordre":{"repliques":[{"qui":"elianne","expression":"neutre","dit":"Sœur Elianne arrive en personne, le visage grave. « Ces escrocs salissent la mémoire des Appelés. Merci. » Ferrand est emmené par deux gardes."}],"effets":[{"flag":"ferrand-arrete","reputation":{"ordre":8},"xp":40}],"choix":[],"suite":"fin","fin":false},"fin":{"repliques":[],"effets":[{"points_guilde":15,"terminer_quete":"q-reliques"}],"choix":[],"fin":true}}},"sq-tanneurs":{"id":"sq-tanneurs","titre":"Les disparus du quartier des Tanneurs","type":"groupe","lieu":"quartier-tanneurs","decor":"quartier-tanneurs","debut":"debut","disponible_si":{"flag":"examen-reussi"},"repetable":false,"romance":false,"quete":"q-tanneurs","noeuds":{"debut":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Les ruelles des Tanneurs sentent l'urine et la teinture. Une mère vous agrippe le bras : « Ma fille, Lina. Partie chercher de l'eau il y a trois jours. »"},{"qui":"narrateur","expression":"neutre","dit":"Des traces de pas, une odeur de soufre… et, gravé sur une porte, un symbole violet que vous commencez à connaître.","si":{"flag":"sceau-trouve"}}],"effets":[{"quete":{"id":"q-tanneurs","etape":"enqueter"}}],"choix":[{"texte":"Suivre la piste de soufre. (Esprit, difficulté 14)","visible_si_bloque":false,"test":{"carac":"ESP","difficulte":14,"reussite":"piste","echec":"retard"},"effets":[]},{"texte":"Interroger les ivrognes du coin, avec quelques pièces. (Charisme, difficulté 13)","visible_si_bloque":false,"test":{"carac":"CHA","difficulte":13,"reussite":"piste","echec":"retard"},"effets":[]}],"fin":false},"piste":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"La piste mène à une cave sous une tannerie abandonnée. Des chants étouffés, des cages… Lina est vivante."}],"effets":[],"choix":[],"combat":{"rencontre":"tanneurs-cultistes","victoire":"sauvee","defaite":"echec"},"fin":false},"retard":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Vous perdez des heures précieuses. Quand vous trouvez enfin la cave, les cultistes vous attendent."}],"effets":[],"choix":[],"combat":{"rencontre":"tanneurs-cultistes","victoire":"trop-tard","defaite":"echec"},"fin":false},"sauvee":{"repliques":[{"qui":"lina","expression":"neutre","dit":"Lina se jette dans les bras de sa mère en pleurant. Les deux autres disparus sont là aussi, affaiblis mais vivants."}],"effets":[{"flag":"lina-sauvee","reputation":{"couronne":5,"guilde":5},"xp":70}],"choix":[],"suite":"fin","fin":false},"trop-tard":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Les cultistes sont vaincus. Deux prisonniers sont sauvés… mais pour Lina, il est trop tard. Sa mère s'effondre."}],"effets":[{"xp":50,"pnj_mort":"lina"}],"choix":[],"suite":"fin","fin":false},"echec":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Vous êtes repoussés. Quand la garde investit la cave le lendemain, elle est vide. On ne retrouvera jamais Lina."}],"effets":[{"reputation":{"couronne":-5},"pnj_mort":"lina"}],"choix":[],"suite":"fin","fin":false},"fin":{"repliques":[],"effets":[{"flag":"cultistes-lysmont","points_guilde":30,"terminer_quete":"q-tanneurs"}],"choix":[],"fin":true}}},"sq-apprenti":{"id":"sq-apprenti","titre":"L'apprenti de l'Ordre","type":"groupe","lieu":"temple-du-seuil","decor":"temple-du-seuil","debut":"debut","disponible_si":{"flag":"examen-reussi"},"repetable":false,"romance":false,"quete":"q-apprenti","noeuds":{"debut":{"repliques":[{"qui":"elianne","expression":"neutre","dit":"« Tobin, mon apprenti, passe ses nuits dans les archives interdites. S'il se fait prendre par le Grand Prieur… » Sœur Elianne se mord la lèvre. « Pouvez-vous lui parler ? »"},{"qui":"tobin","expression":"neutre","dit":"Vous trouvez Tobin entre deux rayonnages, une bougie à la main, un vieux registre ouvert. « Regardez ! Les registres de l'Appel. Il manque des pages. Toujours les mêmes : le prix. »"}],"effets":[{"quete":{"id":"q-apprenti","etape":"parler"}}],"choix":[{"texte":"Lire le registre avec lui.","visible_si_bloque":false,"effets":[{"flag":"indice-prix-appel","xp":30}],"aller":"lire"},{"texte":"Le convaincre de remettre le registre en place avant qu'il ne soit trop tard.","visible_si_bloque":false,"effets":[{"reputation":{"ordre":5}}],"aller":"raisonner"},{"texte":"Le dénoncer au Grand Prieur Mathis.","visible_si_bloque":false,"effets":[{"flag":"tobin-denonce","reputation":{"ordre":10}}],"aller":"denonce"}],"fin":false},"lire":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Une seule ligne a échappé au grattoir : « …et pour chaque Appel, le Voile cède d'un fil, et au nord, les Cendres s'en nourrissent. »"},{"qui":"elianne","expression":"surprise","dit":"Elianne, derrière vous, a tout entendu. Elle est livide."}],"effets":[],"choix":[],"suite":"fin","fin":false},"raisonner":{"repliques":[{"qui":"tobin","expression":"neutre","dit":"Tobin soupire et range le registre. « Vous avez raison. Mais un jour, quelqu'un devra savoir. »"}],"effets":[],"choix":[],"suite":"fin","fin":false},"denonce":{"repliques":[{"qui":"mathis","expression":"neutre","dit":"Le Grand Prieur vous remercie chaleureusement. Le lendemain, Tobin a été « envoyé dans un monastère du nord ». Elianne ne vous adresse plus la parole."}],"effets":[],"choix":[],"suite":"fin","fin":false},"fin":{"repliques":[],"effets":[{"points_guilde":15,"terminer_quete":"q-apprenti"}],"choix":[],"fin":true}}},"sq-tournoi":{"id":"sq-tournoi","titre":"Le tournoi des écuyers","type":"groupe","lieu":"arene","decor":"arene","debut":"debut","disponible_si":{"flag":"examen-reussi"},"repetable":false,"romance":false,"quete":"q-tournoi","noeuds":{"debut":{"repliques":[{"qui":"aveline","expression":"neutre","dit":"Aveline, juge du tournoi, vous accueille. « Un de nos écuyers s'est cassé la jambe. Il me faut un remplaçant. Et un adversaire coriace pour le finaliste : un mercenaire qui triche. »"},{"qui":"aveline","expression":"gene","dit":"« Si vous gagnez… je vous offre une pâtisserie. » Elle se racle la gorge. « C'est une coutume. »"}],"effets":[{"quete":{"id":"q-tournoi","etape":"participer"}}],"choix":[{"texte":"Affronter le mercenaire tricheur.","visible_si_bloque":false,"effets":[],"aller":"combat"}],"fin":false},"combat":{"repliques":[],"effets":[],"choix":[],"combat":{"rencontre":"tournoi-ecuyers","victoire":"victoire","defaite":"defaite"},"fin":false},"victoire":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"La foule rugit. Le mercenaire, désarmé, est escorté hors de l'arène."},{"qui":"aveline","expression":"joie","dit":"Aveline vous tend un gâteau de Lysmont, les joues roses. « Coutume. C'est la coutume. »"}],"effets":[{"reputation":{"couronne":5},"affinite":{"aveline":6},"or":40,"objet":"gateau-lysmont"}],"choix":[],"suite":"fin","fin":false},"defaite":{"repliques":[{"qui":"aveline","expression":"neutre","dit":"« Il trichait, je l'ai vu. » Aveline fait disqualifier le mercenaire. « Vous vous êtes battus honnêtement. C'est ce qui compte. »"}],"effets":[{"affinite":{"aveline":3}}],"choix":[],"suite":"fin","fin":false},"fin":{"repliques":[],"effets":[{"points_guilde":25,"terminer_quete":"q-tournoi"}],"choix":[],"fin":true}}},"prologue-6-ans":{"id":"prologue-6-ans","titre":"Prologue — Les souvenirs d'avant (6 ans, 1000 AV)","type":"individuel","decor":"prologue-campagne","debut":"debut","disponible_si":{"pas_flag":"prologue-6","origine":"reincarne"},"repetable":false,"romance":false,"noeuds":{"debut":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Tu as six ans. Ce matin, en regardant ton reflet dans une flaque, une vague d'images te submerge : des rues éclairées la nuit, des écrans, un nom qui n'est pas le tien… une autre vie, terminée trop tôt."},{"qui":"narrateur","expression":"neutre","dit":"Tu comprends, avec une clarté effrayante, que tu as déjà vécu. Et que ce monde-ci n'est pas le même."},{"qui":"narrateur","expression":"neutre","dit":"Mais d'abord : où as-tu grandi, dans cette nouvelle vie ?"}],"effets":[],"choix":[{"texte":"Dans une ferme près de la Combe-aux-Saules. Des champs de blé à perte de vue.","visible_si_bloque":false,"effets":[{"flag":"heros:prologue-6","origine_enfance":"fermier","journal":"{heros} grandit dans une ferme d'Aubeclaire."}],"aller":"ferme"},{"texte":"Dans le manoir d'une petite famille noble, entre précepteurs et étiquette.","visible_si_bloque":false,"effets":[{"flag":"heros:prologue-6","origine_enfance":"noble","journal":"{heros} grandit dans un manoir de petite noblesse."}],"aller":"manoir"},{"texte":"À l'orphelinat de l'Ordre, sous les cloches de la chapelle blanche.","visible_si_bloque":false,"effets":[{"flag":"heros:prologue-6","origine_enfance":"orphelin","journal":"{heros} grandit à l'orphelinat de l'Ordre."}],"aller":"orphelinat"},{"texte":"Dans l'arrière-boutique encombrée d'un marchand ambulant.","visible_si_bloque":false,"effets":[{"flag":"heros:prologue-6","origine_enfance":"marchand","journal":"{heros} grandit parmi les caisses d'un marchand."}],"aller":"boutique"}],"fin":false},"ferme":{"decor":"prologue-campagne","repliques":[{"qui":"narrateur","expression":"neutre","dit":"La ferme sent le foin et le pain chaud. Ta mère d'ici chante faux, ton père d'ici rit fort. Tu décides de garder ton secret… pour l'instant."}],"effets":[],"choix":[],"suite":"fin","fin":false},"manoir":{"decor":"prologue-manoir","repliques":[{"qui":"narrateur","expression":"neutre","dit":"Les couloirs du manoir résonnent de leçons de maintien. Ton précepteur trouve que tu poses « de bien étranges questions » sur l'électricité."}],"effets":[],"choix":[],"suite":"fin","fin":false},"orphelinat":{"decor":"prologue-orphelinat","repliques":[{"qui":"narrateur","expression":"neutre","dit":"Les sœurs sont strictes mais justes. Tu apprends vite à lire — trop vite, murmure-t-on. Une prêtresse note ton nom dans un registre."}],"effets":[],"choix":[],"suite":"fin","fin":false},"boutique":{"decor":"prologue-boutique","repliques":[{"qui":"narrateur","expression":"neutre","dit":"Entre les épices et les tapis roulés, tu apprends à compter plus vite que les adultes. Le marchand jure que tu lui porteras chance."}],"effets":[],"choix":[],"suite":"fin","fin":false},"fin":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Les souvenirs de ton ancienne vie s'estompent un peu, comme un rêve au réveil. Mais ils ne partent jamais tout à fait."}],"effets":[],"choix":[],"fin":true}}},"prologue-10-ans":{"id":"prologue-10-ans","titre":"Prologue — Le premier secret (10 ans, 1004 AV)","type":"individuel","decor":"prologue-campagne","debut":"debut","disponible_si":{"flag":"prologue-6","pas_flag":"prologue-10","origine":"reincarne"},"repetable":false,"romance":false,"noeuds":{"debut":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Tu as dix ans. Une nuit d'orage, quelque chose s'éveille en toi : ton don. Il frémit sous ta peau, impatient."},{"qui":"narrateur","expression":"neutre","dit":"Un adulte entre dans la pièce au moment exact où ton don se manifeste."}],"effets":[],"choix":[{"texte":"Cacher ton don à tout prix. Personne ne doit savoir.","visible_si_bloque":false,"effets":[{"flag":["heros:prologue-10","heros:enfance-discrete"]}],"aller":"discret"},{"texte":"Lui montrer. Tu as besoin de confier ce secret à quelqu'un.","visible_si_bloque":false,"effets":[{"flag":["heros:prologue-10","heros:enfance-confiance"]}],"aller":"confiance"},{"texte":"T'en servir pour aider : le toit de la grange s'effondre sous la pluie.","visible_si_bloque":false,"effets":[{"flag":["heros:prologue-10","heros:enfance-heroique"]}],"aller":"heroique"}],"fin":false},"discret":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Tu inventes une excuse maladroite. L'adulte hausse les épaules. Tu apprends ce soir-là l'art de te taire — il te servira."}],"effets":[],"choix":[],"suite":"fin","fin":false},"confiance":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"L'adulte reste longtemps silencieux, puis te serre contre lui. « Ce sera notre secret. » Tu n'as jamais été aussi soulagé."}],"effets":[],"choix":[],"suite":"fin","fin":false},"heroique":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Ton don retient la charpente juste assez longtemps pour que les bêtes sortent. On parle de miracle au village. Toi, tu trembles toute la nuit."}],"effets":[],"choix":[],"suite":"fin","fin":false},"fin":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Dès lors, chaque jour, tu t'entraînes en cachette. Ton corps d'enfant apprend ce que ton âme sait déjà."}],"effets":[],"choix":[],"fin":true}}},"prologue-14-ans":{"id":"prologue-14-ans","titre":"Prologue — La rencontre (14 ans, 1008 AV)","type":"individuel","decor":"prologue-campagne","debut":"debut","disponible_si":{"flag":"prologue-10","pas_flag":"prologue-14","origine":"reincarne"},"repetable":false,"romance":false,"noeuds":{"debut":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Tu as quatorze ans. Cette année-là, quelqu'un entre dans ta vie et ne la quitte plus vraiment."}],"effets":[],"choix":[{"texte":"Maître Orlo, un vieux bibliothécaire bourru, qui devine ce que tu es et t'enseigne les légendes de l'Appel.","visible_si_bloque":false,"effets":[{"flag":"heros:prologue-14","contact":"mentor","journal":"{heros} devient l'élève de Maître Orlo."}],"aller":"mentor"},{"texte":"Cassian, fils de garde, fier et rapide. Il te bat à la course, tu le bats aux échecs. Rivaux pour la vie.","visible_si_bloque":false,"effets":[{"flag":"heros:prologue-14","contact":"rival","journal":"{heros} se trouve un rival : Cassian."}],"aller":"rival"},{"texte":"Pipa, rieuse et intrépide, qui t'entraîne dans toutes les bêtises du canton.","visible_si_bloque":false,"effets":[{"flag":"heros:prologue-14","contact":"ami-enfance","journal":"{heros} et Pipa deviennent inséparables."}],"aller":"amie"}],"fin":false},"mentor":{"repliques":[{"qui":"mentor","expression":"neutre","dit":"« Les Appelés d'autrefois… on les dit héros. Moi, je me demande surtout ce qu'ils ont payé pour l'être. »"}],"effets":[],"choix":[],"suite":"fin","fin":false},"rival":{"repliques":[{"qui":"rival","expression":"neutre","dit":"« La prochaine fois, je gagne. Et un jour, je serai dans la garde royale. Toi, tu feras quoi ? »"}],"effets":[],"choix":[],"suite":"fin","fin":false},"amie":{"repliques":[{"qui":"ami-enfance","expression":"neutre","dit":"« Promets-moi qu'un jour on partira voir la mer. Promets ! »"}],"effets":[],"choix":[],"suite":"fin","fin":false},"fin":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Ce lien te suivra jusqu'à Lysmont. Peut-être même au-delà."}],"effets":[],"choix":[],"fin":true}}},"prologue-17-ans":{"id":"prologue-17-ans","titre":"Prologue — Le départ (17 ans, 1011 AV)","type":"individuel","decor":"prologue-route-lysmont","debut":"debut","disponible_si":{"flag":"prologue-14","pas_flag":"prologue-17","origine":"reincarne"},"repetable":false,"romance":false,"noeuds":{"debut":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Tu as dix-sept ans. Depuis des semaines, une vibration te réveille la nuit, venue de la capitale. L'Ordre prépare quelque chose."},{"qui":"narrateur","expression":"neutre","dit":"Tu prends la route de Lysmont au lever du soleil. Avant de partir, tu reçois un dernier conseil… ou un dernier cadeau."}],"effets":[],"choix":[{"texte":"Une lettre de recommandation pour la Guilde (Guilde +10).","visible_si_bloque":false,"effets":[{"flag":"heros:prologue-17","reputation":{"guilde":10},"atout":"lettre-guilde"}],"aller":"fin"},{"texte":"Le sceau d'une famille noble qui te doit service (Couronne +10).","visible_si_bloque":false,"effets":[{"flag":"heros:prologue-17","reputation":{"couronne":10},"atout":"sceau-noble"}],"aller":"fin"},{"texte":"La bénédiction d'une prêtresse de l'orphelinat (Ordre +10).","visible_si_bloque":false,"effets":[{"flag":"heros:prologue-17","reputation":{"ordre":10},"atout":"benediction"}],"aller":"fin"},{"texte":"Une bourse bien remplie, économisée sou après sou (+60 or).","visible_si_bloque":false,"effets":[{"flag":"heros:prologue-17","or":60,"atout":"bourse"}],"aller":"fin"}],"fin":false},"fin":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Au loin, les tours blanches de Lysmont. Dans quelques mois, au printemps 1012, tu auras dix-huit ans… et le Temple du Seuil s'illuminera."},{"qui":"narrateur","expression":"neutre","dit":"(Fin du prologue. Ton histoire rejoint celle des autres héros au chapitre 1.)"}],"effets":[],"choix":[],"fin":true}}}},"quetes":{"q-ch1-appel":{"id":"q-ch1-appel","titre":"Chapitre 1 — L'Appel","type":"principale","chapitre":1,"region":"aubeclaire","resume":"Invoqués ou revenus d'une autre vie, vous voici à Lysmont. Survivez, entrez à la Guilde, et découvrez ce que la Couronne attend de vous.","etapes":[{"id":"appel","objectif":"Écouter le Grand Prieur au Temple du Seuil.","scene":"ch1-appel","lieu":"temple-du-seuil"},{"id":"examen","objectif":"Passer l'examen d'entrée de la Guilde.","scene":"ch1-examen","lieu":"guilde"},{"id":"crypte","objectif":"Explorer la Crypte de la Fontaine (Brumaire 1013).","scene":"ch1-crypte","lieu":"crypte-fontaine"},{"id":"lanternes","objectif":"Assister à la Fête des Lanternes (15 Floréal 1014).","scene":"ch1-lanternes","lieu":"lysmont-place"},{"id":"serment","objectif":"Répondre à la convocation du roi (Nivôse 1014).","scene":"ch1-serment","lieu":"chateau"},{"id":"fin","objectif":"Chapitre terminé."}]},"q-loups":{"id":"q-loups","titre":"Les loups de la Combe-aux-Saules","type":"secondaire","chapitre":1,"region":"aubeclaire","resume":"Gareth le fermier perd ses moutons, et sa fille n'ose plus sortir.","etapes":[{"id":"aider","objectif":"Rendre visite à Gareth dans la Combe-aux-Saules.","scene":"sq-loups","lieu":"combe-aux-saules"}]},"q-reliques":{"id":"q-reliques","titre":"Le marchand de reliques","type":"secondaire","chapitre":1,"region":"aubeclaire","resume":"Au Chaudron Fêlé, un marchand vend des « os de saint » à prix d'or.","etapes":[{"id":"enqueter","objectif":"Approcher Ferrand à la taverne.","scene":"sq-reliques","lieu":"taverne"}]},"q-tanneurs":{"id":"q-tanneurs","titre":"Les disparus du quartier des Tanneur